let lastHover=0,zoomUntil=0;let drag=null;const canvas=renderer.domElement;document.addEventListener('contextmenu',e=>e.preventDefault(),{capture:true});canvas.addEventListener('pointerdown',e=>{if(e.button!==0&&e.button!==2)return;e.preventDefault();canvas.setPointerCapture(e.pointerId);drag={x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,button:e.button,moved:false};$('hover').hidden=true;});canvas.addEventListener('pointermove',e=>{if(drag){const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>5)drag.moved=true;if(!drag.moved)return;if(drag.button===2){yaw-=dx*.006;pitch=THREE.MathUtils.clamp(pitch+dy*.004,.45,1.3)}else{const k=distance*.0008;target.x+=(-dx*Math.cos(yaw)-dy*Math.sin(yaw))*k;target.z+=(dx*Math.sin(yaw)-dy*Math.cos(yaw))*k;target.x=THREE.MathUtils.clamp(target.x,-EXTENT.x,EXTENT.x);target.z=THREE.MathUtils.clamp(target.z,-EXTENT.z,EXTENT.z);}drag.x=e.clientX;drag.y=e.clientY;}else{const time=performance.now();if(time<zoomUntil||Math.abs(distance-wantDistance)>.15||time-lastHover<60){$('hover').hidden=true;return;}lastHover=time;const c=pick(e);$('hover').hidden=!c;if(c){$('hover').style.setProperty('--faction-color',faction(c.owner).color);$('hover').innerHTML='<div class="hover-title">'+c.terrain+'<span>'+faction(c.owner).name+'军</span></div><p>'+(c.walkable?'行军成本 <b>'+c.cost.toFixed(2)+'</b> / 格':'陆军不可通行')+'</p><small>地块 '+c.q+'，'+c.r+' · '+(c.walkable?'左键情报 · 右键移动至':'河流走津渡，险山需绕行')+'</small>';$('hover').style.left=Math.min(innerWidth-260,e.clientX+16)+'px';$('hover').style.top=Math.min(innerHeight-130,e.clientY+18)+'px';}}});canvas.addEventListener('pointerup',e=>{if(drag&&!drag.moved&&e.button===drag.button&&Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)<=5){if(drag.button===2)moveTo(pick(e));else{const c=pick(e);if(c){const city=cities.find(city=>Math.hypot(city.x-c.x,city.z-c.z)<2.7);if(city)inspectCity(city);else selectCell(c);}}}drag=null;});canvas.addEventListener('pointercancel',()=>drag=null);canvas.addEventListener('lostpointercapture',()=>drag=null);canvas.addEventListener('pointerleave',()=>$('hover').hidden=true);canvas.addEventListener('wheel',e=>{e.preventDefault();zoomUntil=performance.now()+180;const delta=e.deltaY*(e.deltaMode===1?16:e.deltaMode===2?innerHeight:1);wantDistance=THREE.MathUtils.clamp(wantDistance*Math.exp(Math.max(-240,Math.min(240,delta))*.001),24,420);$('hover').hidden=true;},{passive:false});document.addEventListener('keydown',e=>{if($('guide').open||$('intelligence').open||e.target.closest('input,select,textarea,[contenteditable]'))return;if(e.key.toLowerCase()==='q'){yaw-=.12;return;}if(e.key.toLowerCase()==='e'){yaw+=.12;return;}if(e.key==='Escape'){clearPreview();return;}if(e.code==='Space'){if(e.ctrlKey||e.altKey||e.metaKey)return;e.preventDefault();if(!e.repeat)$('pause').click();return;}if(e.key==='+'||e.key==='=')wantDistance=Math.max(24,wantDistance*.85);if(e.key==='-')wantDistance=Math.min(420,wantDistance*1.15);});document.addEventListener('keyup',e=>{if(e.code==='Space'&&!$('guide').open&&!$('intelligence').open&&!e.target.closest('input,select,textarea,[contenteditable]'))e.preventDefault();});document.addEventListener('visibilitychange',()=>{if(document.hidden){running=false;updatePanel();}else{previous=performance.now();frames=[];}});
intelligence=createIntelligence({getWorld:()=>world,getSimulation:()=>actorSim,inspectActor,cities,pause:()=>{running=false;updatePanel();},focusCity:city=>{inspectCity(city);target.set(city.x,0,city.z);wantDistance=40;},focusUnit:focus,plan:city=>moveTo(world.nearest(city.x,city.z)),standby:()=>{running=false;world.unit.path=[];marchMotion.retarget();orderRoute.clear();clearPreview();announce('姬衡部队原地待命，尚未完成的路线已撤销。');}});
$('heroInfo').onclick=()=>intelligence.open('officer');$('citiesInfo').onclick=()=>intelligence.open('cities');$('unitsInfo').onclick=()=>intelligence.open('unit');$('info').onclick=()=>intelligence.open('realm');$('officersInfo').onclick=()=>intelligence.open('roster');$('cmdMarch').onclick=()=>{showUnit();focus();announce('右键地图或城市下达行军命令，左键仍可查看情报。');};$('cmdReturn').onclick=()=>moveTo(world.origin);$('cmdStandby').onclick=()=>$('cancel').click();$('cmdStep').onclick=()=>$('step').click();$('journal').onclick=()=>intelligence.open('journal');$('officerInfo').onclick=()=>intelligence.open('officer');$('unitInfo').onclick=()=>intelligence.open('unit');intelligence.record('先遣旅已集结于绛，等待军令。');
function showUnit(){running=false;sidebar?.showUnit();for(const l of cityLabels){l.el.classList.remove('selected-city');l.el.setAttribute('aria-pressed','false');}updatePanel();}
function inspectCity(city){running=false;clearPreview();sidebar?.showCity(city);for(const l of cityLabels){l.el.classList.toggle('selected-city',l.city.name===city.name);l.el.setAttribute('aria-pressed',String(l.city.name===city.name));}updatePanel();}
function inspectActor(id){running=false;clearPreview();sidebar?.showActor(id);for(const l of cityLabels){l.el.classList.remove('selected-city');l.el.setAttribute('aria-pressed','false');}updatePanel();}
sidebar=createSidebar({getWorld:()=>world,getSimulation:()=>actorSim,cities,onOfficer:id=>intelligence.openOfficer(id),onActor:inspectActor,onLocateActor:id=>{const a=actorSim.actors.find(a=>a.id===id),p=actorSim.position(a);target.set(p.x,0,p.z);wantDistance=65;},onInspect:inspectCity,onUnit:showUnit,onLocate:city=>{target.set(city.x,0,city.z);wantDistance=45;},onPlan:city=>moveTo(world.nearest(city.x,city.z))});
function resize(){renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();}addEventListener('resize',resize);resize();updatePanel();moveCamera();function label(el,point){const p=projectAnchor(point,camera,mapRoot,innerWidth,innerHeight),ratio=renderer.getPixelRatio();el.hidden=p.depth>1||p.depth< -1||p.x<0||p.x>innerWidth||p.y<80||p.y>innerHeight-75;const x=Math.round(p.x*ratio)/ratio,y=Math.round(p.y*ratio)/ratio;el._mapX=x;el._mapY=y;const value=x+'px '+y+'px';if(el.style.translate!==value)el.style.translate=value;}
const actorView=createActorView({root:mapRoot,getSimulation:()=>actorSim,label,onInspect:inspectActor});
let lastActorPanel=0;

// Keep every city clickable; crowded names collapse to their faction standard.
function declutterCities(){
 const far=overview.amount>.75,w=far?78:145,h=far?30:48,occupied=[];
 const ordered=cityLabels.slice().sort((a,b)=>Number(b.el.classList.contains('hero-resident')||b.el.classList.contains('selected-city'))-Number(a.el.classList.contains('hero-resident')||a.el.classList.contains('selected-city')));
 for(const l of ordered){if(l.el.hidden)continue;const x=l.el._mapX,y=l.el._mapY;const crowded=occupied.some(r=>Math.abs(x-r.x)<(w+r.w)/2+3&&Math.abs(y-r.y)<h+3);l.el.classList.toggle('compact-city',crowded);occupied.push({x,y,w:crowded?(far?20:26):w});}
}
const mapPeek=createMapPeek({getWorld:()=>world,getSimulation:()=>actorSim});
const perfProbe=createPerformanceProbe({start:()=>{const saved={distance:wantDistance,target:target.clone(),yaw,pitch};running=false;target.set(0,0,1);yaw=0;pitch=.78;updatePanel();return saved;},aim:d=>wantDistance=d,restore:s=>{wantDistance=s.distance;target.copy(s.target);yaw=s.yaw;pitch=s.pitch;}});
const setupMs=performance.now()-setupStarted;
let previous=performance.now(),frames=[],lastMetrics=0,lastShadow=0,lastShadowScale=-1;function render(now){requestAnimationFrame(render);if(document.hidden)return;const dt=now-previous;previous=now;if(dt>0&&dt<10000)frames.push(dt);if(frames.length>600)frames.shift();const frameStarted=performance.now();perfProbe.tick(now);moveCamera();if(running)actorSim.advance(Math.min(100,Math.max(0,dt)));gridMesh.visible=showGrid;if(running&&world.unit.path.length){if(world.unit.morale<=0)advance();else marchMotion.advance(Math.min(100,Math.max(0,dt)));}const {x,z}=marchMotion.position();army.position.set(x,Math.max(.48,height(x,z)),z);orderRoute.follow(x,army.position.y,z);unitRing.position.set(x,Math.max(.48,height(x,z))+.06,z);const residentCity=cityAt(x,z);army.visible=unitRing.visible=!residentCity;for(const l of cityLabels){l.badge.hidden=l.city!==residentCity;l.el.classList.toggle('hero-resident',l.city===residentCity);label(l.el,l.point);}declutterCities();for(const r of regionLabels)label(r.el,r.point);if(residentCity)armyLabel.hidden=true;else label(armyLabel,new THREE.Vector3(x,army.position.y+2.3,z));actorView.update();mapPeek.update(now);if(now-lastActorPanel>400){lastActorPanel=now;if(sidebar?.mode!=='unit')sidebar?.refresh();}riverArt.animate(now);if(renderer.shadowMap.enabled&&(running||Math.abs(mapRoot.scale.y-lastShadowScale)>.001)&&now-lastShadow>80){renderer.shadowMap.needsUpdate=true;lastShadow=now;lastShadowScale=mapRoot.scale.y;}renderer.render(scene,camera);perfProbe.frameCost(performance.now()-frameStarted);if(now-lastMetrics>700&&frames.length){lastMetrics=now;const sorted=[...frames].sort((a,b)=>a-b),avg=frames.reduce((a,b)=>a+b,0)/frames.length;$('metrics').textContent=Math.round(1000/avg)+' FPS · P95 '+sorted[Math.floor(sorted.length*.95)].toFixed(1)+' ms\n'+world.cells.length+' 地块 · '+renderer.info.render.calls+' 绘制 · '+(renderer.info.render.triangles/1000).toFixed(0)+'k 面\n'+cities.length+' 城 · '+factions.length+' 势力 · 建图 '+Math.round(setupMs)+' ms · 慢帧 '+frames.filter(t=>t>33.4).length+'/'+frames.length;}}requestAnimationFrame(render);$('loading').hidden=true;
